package fizeau

import (
	"context"

	"github.com/easel/fizeau/internal/discoverycache"
	"github.com/easel/fizeau/internal/modelcatalog"
	"github.com/easel/fizeau/internal/modelsnapshot"
)

func assembleModelSnapshotFromServiceConfig(ctx context.Context, sc ServiceConfig, cat *modelcatalog.Catalog, cacheRoot string) (modelsnapshot.ModelSnapshot, error) {
	return assembleModelSnapshotFromServiceConfigWithOptions(ctx, sc, cat, cacheRoot, modelsnapshot.AssembleOptions{Refresh: modelsnapshot.RefreshBackground})
}

func assembleModelSnapshotFromServiceConfigWithOptions(ctx context.Context, sc ServiceConfig, cat *modelcatalog.Catalog, cacheRoot string, opts modelsnapshot.AssembleOptions) (modelsnapshot.ModelSnapshot, error) {
	var cfg *modelsnapshot.Config
	if sc != nil {
		cfg = serviceConfigToModelSnapshotConfig(sc)
	}
	cache := &discoverycache.Cache{Root: cacheRoot}
	return modelsnapshot.AssembleWithOptions(ctx, cfg, cat, cache, opts)
}

func serviceConfigToModelSnapshotConfig(sc ServiceConfig) *modelsnapshot.Config {
	if sc == nil {
		return nil
	}
	cfg := &modelsnapshot.Config{
		Default:   sc.DefaultProviderName(),
		Providers: make(map[string]modelsnapshot.ProviderConfig, len(sc.ProviderNames())),
	}
	for _, name := range sc.ProviderNames() {
		entry, ok := sc.Provider(name)
		if !ok {
			continue
		}
		cfg.Providers[name] = modelSnapshotProviderConfig(entry)
	}
	return cfg
}

func modelSnapshotProviderConfig(entry ServiceProviderEntry) modelsnapshot.ProviderConfig {
	out := modelsnapshot.ProviderConfig{
		Type:             entry.Type,
		BaseURL:          entry.BaseURL,
		ServerInstance:   entry.ServerInstance,
		Endpoints:        make([]modelsnapshot.ProviderEndpoint, 0, len(entry.Endpoints)),
		APIKey:           entry.APIKey,
		Headers:          cloneStringMap(entry.Headers),
		Model:            entry.Model,
		Billing:          string(entry.Billing),
		IncludeByDefault: nil,
		ContextWindow:    entry.ContextWindow,
		ConfigError:      entry.ConfigError,
		DailyTokenBudget: entry.DailyTokenBudget,
	}
	if entry.IncludeByDefaultSet {
		v := entry.IncludeByDefault
		out.IncludeByDefault = &v
		out.IncludeByDefaultSet = true
	}
	for _, endpoint := range entry.Endpoints {
		out.Endpoints = append(out.Endpoints, modelsnapshot.ProviderEndpoint{
			Name:           endpoint.Name,
			BaseURL:        endpoint.BaseURL,
			ServerInstance: endpoint.ServerInstance,
		})
	}
	return out
}

func cloneStringMap(src map[string]string) map[string]string {
	if len(src) == 0 {
		return nil
	}
	out := make(map[string]string, len(src))
	for k, v := range src {
		out[k] = v
	}
	return out
}

package config

import (
	"path/filepath"
	"time"

	fizeau "github.com/easel/fizeau"
)

func init() {
	// Register the config loader into the root package so that fizeau.New can
	// load configuration without importing this package directly (which would
	// create an import cycle: config → agent → config).
	fizeau.RegisterConfigLoader(func(dir string) (fizeau.ServiceConfig, error) {
		cfg, err := Load(dir)
		if err != nil {
			return nil, err
		}
		return &configServiceConfig{cfg: cfg, baseDir: dir}, nil
	})
}

// configServiceConfig wraps a loaded *Config and satisfies fizeau.ServiceConfig.
// It is the agent-internal equivalent of DDx's ServiceConfigAdapter.
type configServiceConfig struct {
	cfg     *Config
	baseDir string
}

func NewServiceConfig(cfg *Config, baseDir string) fizeau.ServiceConfig {
	return &configServiceConfig{cfg: cfg, baseDir: baseDir}
}

func (c *configServiceConfig) ProviderNames() []string {
	if c.cfg == nil {
		return nil
	}
	return c.cfg.ProviderNames()
}

func (c *configServiceConfig) DefaultProviderName() string {
	if c.cfg == nil {
		return ""
	}
	return c.cfg.DefaultName()
}

func (c *configServiceConfig) Provider(name string) (fizeau.ServiceProviderEntry, bool) {
	if c.cfg == nil {
		return fizeau.ServiceProviderEntry{}, false
	}
	pc, ok := c.cfg.Providers[name]
	if !ok {
		return fizeau.ServiceProviderEntry{}, false
	}
	endpoints := make([]fizeau.ServiceProviderEndpoint, 0, len(pc.Endpoints))
	for _, endpoint := range pc.Endpoints {
		endpoints = append(endpoints, fizeau.ServiceProviderEndpoint{
			Name:           endpoint.Name,
			BaseURL:        endpoint.BaseURL,
			ServerInstance: endpoint.ServerInstance,
		})
	}
	return fizeau.ServiceProviderEntry{
		Type:                pc.Type,
		BaseURL:             pc.BaseURL,
		ServerInstance:      pc.ServerInstance,
		Endpoints:           endpoints,
		APIKey:              pc.APIKey,
		Headers:             pc.Headers,
		Model:               pc.Model,
		Billing:             c.cfg.ProviderBilling(name),
		IncludeByDefault:    c.cfg.ProviderIncludeByDefault(name),
		IncludeByDefaultSet: true,
		ContextWindow:       pc.ContextWindow,
		ConfigError:         c.cfg.ProviderError(name),
		DailyTokenBudget:    pc.DailyTokenBudget,
	}, true
}

func (c *configServiceConfig) HealthCooldown() time.Duration {
	if c.cfg == nil || c.cfg.Routing.HealthCooldown == "" {
		return 0
	}
	d, err := time.ParseDuration(c.cfg.Routing.HealthCooldown)
	if err != nil {
		return 0
	}
	return d
}

func (c *configServiceConfig) WorkDir() string {
	return c.baseDir
}

func (c *configServiceConfig) SessionLogDir() string {
	workDir := c.WorkDir()
	configured := ""
	if c.cfg != nil {
		configured = c.cfg.SessionLogDir
	}
	if configured != "" {
		if filepath.IsAbs(configured) {
			return configured
		}
		if workDir == "" {
			return configured
		}
		return filepath.Join(workDir, configured)
	}
	if workDir == "" {
		return ""
	}
	return filepath.Join(workDir, ProjectConfigDirName(), "sessions")
}

