		name = endpointNameForConfig(providerName, pc.BaseURL, nil)
	}
	return []modelDiscoveryEndpoint{{
		Name:           name,
		BaseURL:        strings.TrimSpace(pc.BaseURL),
		ServerInstance: firstServerInstance(pc),
	}}
}

