// ListModels returns models matching the filter, with full metadata.
// Empty filter returns all models from every reachable provider.
func (s *service) ListModels(ctx context.Context, filter ModelFilter) ([]ModelInfo, error) {
	if filter.Harness != "" && harnesses.ResolveHarnessAlias(filter.Harness) != "fiz" {
		return s.listModelsForSubprocessHarness(filter), nil
	}

	sc := s.opts.ServiceConfig
	if sc == nil {
		return nil, fmt.Errorf("service: no ServiceConfig provided; pass ServiceOptions.ServiceConfig")
	}

	cat, _ := modelcatalog.Default() // ignore error: catalog miss is non-fatal
	cacheRoot, err := serviceModelCacheRoot()
	if err != nil {
		return nil, err
	}
	snapshot, err := assembleModelSnapshotFromServiceConfigWithOptions(ctx, sc, cat, cacheRoot, modelsnapshot.AssembleOptions{Refresh: modelsnapshot.RefreshForce})
	if err != nil {
		return nil, err
	}
	return s.listModelsFromSnapshot(ctx, sc, cat, snapshot, filter), nil
}

func serviceModelCacheRoot() (string, error) {
	if override := strings.TrimSpace(os.Getenv("FIZEAU_CACHE_DIR")); override != "" {
		return override, nil
	}
	cacheDir, err := os.UserCacheDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(cacheDir, "fizeau"), nil
}

func (s *service) listModelsFromSnapshot(ctx context.Context, sc ServiceConfig, cat *modelcatalog.Catalog, snapshot modelsnapshot.ModelSnapshot, filter ModelFilter) []ModelInfo {
	defaultProviderName := sc.DefaultProviderName()
	var out []ModelInfo
	for _, providerName := range sc.ProviderNames() {
		if filter.Provider != "" && filter.Provider != providerName {
			continue
		}
		entry, ok := sc.Provider(providerName)
		if !ok {
			continue
		}
		rows := snapshotRowsForProvider(snapshot.Models, providerName)
		if len(rows) == 0 {
			continue
		}
		isDefaultProvider := providerName == defaultProviderName
		for i, row := range rows {
			out = append(out, s.modelInfoFromSnapshotRow(ctx, providerName, entry, cat, row, isDefaultProvider, i))
		}
	}
	return out
}

func snapshotRowsForProvider(models []modelsnapshot.KnownModel, providerName string) []modelsnapshot.KnownModel {
	out := make([]modelsnapshot.KnownModel, 0, len(models))
	for _, model := range models {
		if model.Provider == providerName {
			out = append(out, model)
		}
	}
	return out
}

func (s *service) modelInfoFromSnapshotRow(
	ctx context.Context,
	providerName string,
	entry ServiceProviderEntry,
	cat *modelcatalog.Catalog,
	row modelsnapshot.KnownModel,
	isDefaultProvider bool,
	rankPosition int,
) ModelInfo {
	rowEntry := entry
	if row.EndpointBaseURL != "" {
		rowEntry.BaseURL = row.EndpointBaseURL
	}
	if row.ServerInstance != "" {
		rowEntry.ServerInstance = row.ServerInstance
	}

	info := ModelInfo{
		ID:              row.ID,
		Provider:        providerName,
		ProviderType:    row.ProviderType,
		Harness:         row.Harness,
		EndpointName:    row.EndpointName,
		EndpointBaseURL: row.EndpointBaseURL,
		ServerInstance:  row.ServerInstance,
		ContextLength:   row.ContextWindow,
		Utilization:     RouteUtilizationState{},
		Cost: CostInfo{
			InputPerMTok:  row.CostInputPerM,
			OutputPerMTok: row.CostOutputPerM,
		},
		PerfSignal: PerfSignal{},
		Power:      row.Power,
		AutoRoutable: row.AutoRoutable,
		ExactPinOnly: row.ExactPinOnly,
		Billing:    row.Billing,
		Available:  true,
		IsDefault:  isDefaultProvider && entry.Model != "" && row.ID == entry.Model,
		RankPosition: rankPosition,
	}

	if row.ProviderType != "" {
		info.Capabilities = providerCapabilities(ServiceProviderEntry{Type: row.ProviderType})
	} else {
		info.Capabilities = providerCapabilities(entry)
	}
	if cat != nil {
		if entry, ok := cat.LookupModel(row.ID); ok {
			info.PerfSignal = PerfSignal{
				SpeedTokensPerSec: entry.SpeedTokensPerSec,
				SWEBenchVerified:  entry.SWEBenchVerified,
			}
		}
	}
	if length, source := resolveContextEvidence(ctx, rowEntry, row.ID, cat); length > 0 {
		info.ContextLength = length
		info.ContextSource = source
	}
	if s.routeUtilizationEvidence != nil {
		info.Utilization = s.routeUtilizationEvidence(providerName, info.ServerInstance, info.EndpointName, row.ID)
	}
	return info
}

func (s *service) listModelsForSubprocessHarness(filter ModelFilter) []ModelInfo {
	name := harnesses.ResolveHarnessAlias(filter.Harness)
	cfg, ok := s.registry.Get(name)
	modelIDs := subprocessHarnessModelIDs(name, cfg)
	if !ok || harnessRunsInProcessOrHTTP(cfg) || len(modelIDs) == 0 {
		return nil
	}
	if filter.Provider != "" && filter.Provider != name {
		return nil
	}
	cat, _ := modelcatalog.Default()
	out := make([]ModelInfo, 0, len(modelIDs))
	for i, id := range modelIDs {
		info := ModelInfo{
			ID:             id,
			Provider:       name,
			Harness:        name,
			EndpointName:   name,
			ServerInstance: name,
			Capabilities:   []string{"streaming", "tool_use"},
			Available:      true,
			IsDefault:      cfg.DefaultModel != "" && id == cfg.DefaultModel,
			Billing:        harnessPaymentKind(name, cfg),
			RankPosition:   i,
		}
		if cat != nil {
			info.ContextLength, info.ContextSource = resolveContextEvidence(context.Background(), ServiceProviderEntry{}, id, cat)
			info.Cost, info.PerfSignal = catalogCostAndPerf(cat, id)
			info.Power, info.AutoRoutable, info.ExactPinOnly = catalogPowerEligibility(cat, id)
		}
		info.Utilization = s.routeUtilizationEvidence(name, info.ServerInstance, info.EndpointName, id)
		out = append(out, info)
	}
	return out
}

