 56	func serviceModelCacheRoot() (string, error) {
 57		if override := strings.TrimSpace(os.Getenv("FIZEAU_CACHE_DIR")); override != "" {
 58			return override, nil
 59		}
 60		cacheDir, err := os.UserCacheDir()
 61		if err != nil {
 62			return "", err
 63		}
 64		return filepath.Join(cacheDir, "fizeau"), nil
