 67	func (s *service) listModelsFromSnapshot(ctx context.Context, sc ServiceConfig, cat *modelcatalog.Catalog, snapshot modelsnapshot.ModelSnapshot, filter ModelFilter) []ModelInfo {
 68		defaultProviderName := sc.DefaultProviderName()
 69		var out []ModelInfo
 70		for _, providerName := range sc.ProviderNames() {
 71			if filter.Provider != "" && filter.Provider != providerName {
 72				continue
 73			}
 74			entry, ok := sc.Provider(providerName)
 75			if !ok {
 76				continue
 77			}
 78			rows := snapshotRowsForProvider(snapshot.Models, providerName)
 79			if len(rows) == 0 {
 80				continue
 81			}
 82			isDefaultProvider := providerName == defaultProviderName
 83			for i, row := range rows {
 84				out = append(out, s.modelInfoFromSnapshotRow(ctx, providerName, entry, cat, row, isDefaultProvider, i))
 85			}
 86		}
 87		return out
 88	}
