 90	func snapshotRowsForProvider(models []modelsnapshot.KnownModel, providerName string) []modelsnapshot.KnownModel {
 91		out := make([]modelsnapshot.KnownModel, 0, len(models))
 92		for _, model := range models {
 93			if model.Provider == providerName {
 94				out = append(out, model)
 95			}
 96		}
 97		return out
 98	}
