328	// resolveContextEvidence resolves the context window for a model using the
329	// precedence chain: provider config > provider API > catalog > default.
330	func resolveContextEvidence(ctx context.Context, entry ServiceProviderEntry, modelID string, cat *modelcatalog.Catalog) (int, string) {
331		modelID = strings.TrimSpace(modelID)
332		if modelID == "" {
333			return 0, ContextSourceUnknown
334		}
335		if entry.ContextWindow > 0 {
336			return entry.ContextWindow, ContextSourceProviderConfig
337		}
338		if limits, source := providerAPIContextEvidence(ctx, entry, modelID); limits > 0 {
339			return limits, source
340		}
341		if cat != nil {
342			if n := cat.ContextWindowForModel(modelID); n > 0 {
343				return n, ContextSourceCatalog
344			}
345		}
346		return compaction.DefaultContextWindow, ContextSourceDefault
347	}
